package com.kongye.floatball;
import android.app.*;
import android.content.*;
import android.content.pm.ServiceInfo;
import android.content.res.Configuration;
import android.graphics.*;
import android.media.projection.*;
import android.os.*;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import java.util.*;

public class ScreenRecordingService extends Service {
    static final String STOP="com.kongye.floatball.STOP_RECORDING",PAUSE="com.kongye.floatball.PAUSE_RECORDING",SHOW="com.kongye.floatball.SHOW_RECORDING",EDIT="com.kongye.floatball.EDIT_RECORDING",EXIT="com.kongye.floatball.EXIT_RECORDING";public static boolean running;private WindowManager recordWindows;
    private final Handler main=new Handler(Looper.getMainLooper());private MediaProjection projection;private RecordingEngine engine;private RecordingSpec spec;private View control;private TextView clock;private RecordingInk ink;private boolean ending,released,destroyed,expanded,exitRequested;private int rotation,x,y;private long started;
    private final BroadcastReceiver screenOff=new BroadcastReceiver(){public void onReceive(Context c,Intent i){stopRecording();}};
    @Override public void onCreate(){super.onCreate();recordWindows=OverlayWindows.get(this);NotificationManager n=getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel("recording","空叶录屏",NotificationManager.IMPORTANCE_LOW));n.createNotificationChannel(new NotificationChannel("recording_result","录制结果",NotificationManager.IMPORTANCE_DEFAULT));if(Build.VERSION.SDK_INT>=33)registerReceiver(screenOff,new IntentFilter(Intent.ACTION_SCREEN_OFF),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(screenOff,new IntentFilter(Intent.ACTION_SCREEN_OFF));}
    @Override public int onStartCommand(Intent intent,int flags,int id){if(intent==null||STOP.equals(intent.getAction())){stopRecording();return START_NOT_STICKY;}if(EXIT.equals(intent.getAction())){exitRequested=true;stopRecording();return START_NOT_STICKY;}if(PAUSE.equals(intent.getAction())){togglePause();return START_NOT_STICKY;}if(SHOW.equals(intent.getAction())){if(running){expanded=true;showControl(true);}return START_NOT_STICKY;}if(EDIT.equals(intent.getAction())){edit();return START_NOT_STICKY;}if(running)return START_NOT_STICKY;
        try{spec=RecordingSpec.read(intent);int type=ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION;if((spec.audio.equals("microphone")||spec.audio.equals("both"))&&Build.VERSION.SDK_INT>=30)type|=ServiceInfo.FOREGROUND_SERVICE_TYPE_MICROPHONE;if(Build.VERSION.SDK_INT>=29)startForeground(1002,notification("准备录制，3 秒后开始"),type);else startForeground(1002,notification("准备录制，3 秒后开始"));Intent data=intent.getParcelableExtra("projection");if(data==null)throw new IllegalArgumentException("缺少系统授权");projection=getSystemService(MediaProjectionManager.class).getMediaProjection(intent.getIntExtra("result_code",Activity.RESULT_CANCELED),data);if(projection==null)throw new IllegalStateException("录制授权无效");projection.registerCallback(new MediaProjection.Callback(){public void onStop(){stopRecording();}},main);rotation=recordWindows.getDefaultDisplay().getRotation();engine=new RecordingEngine(this,projection,spec);ink=new RecordingInk(this);running=true;ending=false;released=false;exitRequested=false;started=0;int[] anchor=FloatService.instance==null?new int[]{screenWidth()-dp(58),dp(100)}:FloatService.instance.recordingAnchor();x=anchor[0];y=anchor[1];if(FloatService.instance!=null)FloatService.instance.recordingChanged();expanded=false;showControl(false);Prefs.of(this).edit().putString("recording_state","countdown").apply();for(int second=0;second<3;second++){int remaining=3-second;main.postDelayed(()->{if(running&&!ending){if(clock!=null)clock.setText(""+remaining);getSystemService(NotificationManager.class).notify(1002,notification("倒计时 "+remaining+" 秒"));}},second*1000L);}main.postDelayed(()->{if(ending||!running)return;started=SystemClock.elapsedRealtime();Prefs.of(this).edit().putString("recording_state","recording").putString("recording_audio",spec.audio).apply();if(spec.hide)removeControl();new Thread(()->engine.run(result->main.post(()->completed(result))),"Kongye-Recorder").start();tick.run();},3000);
        }catch(RuntimeException e){Toast.makeText(this,"无法开始录制："+e.getMessage(),Toast.LENGTH_LONG).show();release();stopSelf();}return START_NOT_STICKY;}
    private int dp(float n){return Ui.dp(this,n);}
    private int screenWidth(){android.util.DisplayMetrics m=new android.util.DisplayMetrics();recordWindows.getDefaultDisplay().getRealMetrics(m);return m.widthPixels;}
    private int screenHeight(){android.util.DisplayMetrics m=new android.util.DisplayMetrics();recordWindows.getDefaultDisplay().getRealMetrics(m);return m.heightPixels;}
    private PendingIntent service(String action,int id){return PendingIntent.getService(this,id,new Intent(this,ScreenRecordingService.class).setAction(action),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);}
    private Notification notification(String text){return new Notification.Builder(this,"recording").setSmallIcon(R.drawable.ic_leaf_notification).setContentTitle(spec!=null&&spec.gif?"空叶 GIF 录制":"空叶正在录屏").setContentText(text).setOngoing(true).setContentIntent(service(SHOW,31)).addAction(new Notification.Action.Builder(null,engine!=null&&engine.isPaused()?"继续":"暂停",service(PAUSE,32)).build()).addAction(new Notification.Action.Builder(null,"停止",service(STOP,33)).build()).addAction(new Notification.Action.Builder(null,"画面标注",service(EDIT,34)).build()).addAction(new Notification.Action.Builder(null,"取消录制",service(EXIT,36)).build()).build();}
    private final Runnable tick=new Runnable(){public void run(){if(!running||ending||started==0)return;long seconds=engine.durationMs()/1000;String time=String.format(Locale.getDefault(),"%02d:%02d",seconds/60,seconds%60);if(clock!=null)clock.setText(time);getSystemService(NotificationManager.class).notify(1002,notification((engine.isPaused()?"已暂停 ":"已录制 ")+time));main.postDelayed(this,500);}};
    private View bubble(String icon,String label,int color,Runnable click){FrameLayout v=new FrameLayout(this);v.setContentDescription(label);v.setBackground(Ui.bg(color,100,this));v.setElevation(dp(4));v.addView(Ui.icon(this,icon,Color.WHITE,24),new FrameLayout.LayoutParams(dp(24),dp(24),Gravity.CENTER));v.setOnClickListener(w->click.run());return v;}
    private void showControl(boolean force){
        removeControl();if(!Settings.canDrawOverlays(this)||(!force&&spec.hide&&started!=0))return;
        boolean right=x+dp(27)>screenWidth()/2;int width=dp(expanded?160:58),height=dp(expanded?286:66),coreX=expanded?dp(right?96:10):0,coreY=expanded?dp(116):0;
        WindowManager.LayoutParams p=new WindowManager.LayoutParams(width,height,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.LEFT;p.x=Math.max(0,Math.min(screenWidth()-width,x-coreX));p.y=Math.max(dp(30),Math.min(screenHeight()-height,y-coreY));x=p.x+coreX;y=p.y+coreY;p.setTitle("空叶录制控制");if(Build.VERSION.SDK_INT>=30)p.setFitInsetsTypes(0);
        int[] origin=new int[2];DragOverlay root=new DragOverlay(this,()->{origin[0]=p.x;origin[1]=p.y;},(dx,dy)->{p.x=Math.max(0,Math.min(screenWidth()-width,origin[0]+Math.round(dx)));p.y=Math.max(dp(30),Math.min(screenHeight()-height,origin[1]+Math.round(dy)));x=p.x+coreX;y=p.y+coreY;if(control!=null&&control.getLayoutParams()==p)recordWindows.updateViewLayout(control,p);receipt(p,coreX,coreY);});root.setContentDescription("录制控制图标，可拖动");
        View anchor=bubble(spec.gif?"gif_record":"record","展开录制控制",0xFF0098D0,()->{expanded=!expanded;showControl(true);});FrameLayout.LayoutParams ap=new FrameLayout.LayoutParams(dp(54),dp(54));ap.leftMargin=coreX;ap.topMargin=coreY;root.addView(anchor,ap);
        clock=Ui.centeredText(this,"00:00",9,Color.WHITE,true);clock.setBackground(Ui.bg(0xCC101C2B,9,this));clock.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(dp(54),dp(18));cp.leftMargin=coreX;cp.topMargin=coreY+dp(46);root.addView(clock,cp);
        if(expanded){addControl(root,engine!=null&&engine.isPaused()?"play":"pause",engine!=null&&engine.isPaused()?"继续录制":"暂停录制",0xFFFFCB25,this::togglePause,right?94:8,6);addControl(root,"stop","停止录制",0xFFC2185B,this::stopRecording,right?8:94,62);addControl(root,"edit","编辑录制画面",0xFF6AA631,this::edit,right?8:94,174);addControl(root,"close","取消录制",0xFF526979,()->{exitRequested=true;stopRecording();},right?94:8,230);}
        control=root;recordWindows.addView(root,p);receipt(p,coreX,coreY);
    }
    private void addControl(FrameLayout root,String icon,String label,int color,Runnable action,int x,int y){View view=bubble(icon,label,color,action);FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(dp(48),dp(48));p.leftMargin=dp(x);p.topMargin=dp(y);root.addView(view,p);}
    private void receipt(WindowManager.LayoutParams p,int cx,int cy){if((getApplicationInfo().flags&android.content.pm.ApplicationInfo.FLAG_DEBUGGABLE)!=0)Prefs.of(this).edit().putInt("qa_record_control_x",p.x).putInt("qa_record_control_y",p.y).putInt("qa_record_anchor_x",x).putInt("qa_record_anchor_y",y).putInt("qa_record_core_x",cx).putInt("qa_record_core_y",cy).putBoolean("qa_record_expanded",expanded).apply();}
    private void removeControl(){if(control!=null){try{recordWindows.removeView(control);}catch(IllegalArgumentException ignored){}control=null;clock=null;}}
    private void togglePause(){if(!running||ending||started==0||engine==null)return;engine.setPaused(!engine.isPaused());Prefs.of(this).edit().putString("recording_state",engine.isPaused()?"paused":"recording").apply();if(control!=null)showControl(true);getSystemService(NotificationManager.class).notify(1002,notification(engine.isPaused()?"已暂停":"继续录制"));}
    private void edit(){if(!running||ending||started==0)return;removeControl();ink.edit();main.postDelayed(()->{if(running&&!ending)showControl(true);},180);}
    private void stopRecording(){if(ending||released)return;ending=true;main.removeCallbacksAndMessages(null);removeControl();if(ink!=null)ink.close();if(started==0){release();if(exitRequested&&!destroyed)returnToSetup();stopSelf();}else if(engine!=null)engine.requestStop();else{release();if(exitRequested&&!destroyed)returnToSetup();stopSelf();}}
    private void completed(RecordingEngine.Result result){release();if(exitRequested&&!destroyed){returnToSetup();stopSelf();return;}if(!destroyed&&result.file!=null){Intent preview=new Intent(this,RecordingResultActivity.class).putExtra("path",result.file.getPath()).putExtra("auto_gif",spec.gif).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_MULTIPLE_TASK);PendingIntent open=PendingIntent.getActivity(this,35,preview,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);getSystemService(NotificationManager.class).notify(1003,new Notification.Builder(this,"recording_result").setSmallIcon(R.drawable.ic_leaf_notification).setContentTitle("录制完成").setContentText("点击预览、保存或分享").setContentIntent(open).setAutoCancel(true).build());if(!exitRequested)try{startActivity(preview);}catch(RuntimeException ignored){}}else if(!destroyed)Toast.makeText(this,"录制未完成："+result.error,Toast.LENGTH_LONG).show();stopSelf();}
    private void returnToSetup(){if(spec==null)return;Intent setup=spec.write(new Intent(this,ScreenRecordingActivity.class)).putExtra("resume_setup",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);try{startActivity(setup);}catch(RuntimeException e){Toast.makeText(this,"无法返回录制准备，请重新打开录制",Toast.LENGTH_LONG).show();}}
    private void release(){if(released)return;released=true;running=false;ending=true;if(FloatService.instance!=null)FloatService.instance.recordingChanged();main.removeCallbacksAndMessages(null);removeControl();if(ink!=null)ink.close();Prefs.of(this).edit().putString("recording_state","idle").apply();if(projection!=null){MediaProjection p=projection;projection=null;p.stop();}stopForeground(STOP_FOREGROUND_REMOVE);}
    @Override public void onConfigurationChanged(Configuration config){super.onConfigurationChanged(config);if(running&&recordWindows.getDefaultDisplay().getRotation()!=rotation)stopRecording();}
    @Override public IBinder onBind(Intent i){return null;}
    @Override public void onDestroy(){destroyed=true;if(engine!=null)engine.requestStop();release();try{unregisterReceiver(screenOff);}catch(IllegalArgumentException ignored){}super.onDestroy();}
}
